/**
 * Crow Studio — the panel's Web MIDI access, as one inline classic script.
 *
 * Like `panel/client.js` and `panel/take-store.js` this travels as a string
 * (`MIDI_SCRIPT`) and is written as an EXPRESSIONS ONLY classic script: no
 * backtick, no `${`, no double quote and no backslash anywhere in the emitted
 * text. It assigns one global — `window.StudioMidi` — and builds nothing in the
 * DOM: the page draws the devices, the list and the Learn outline itself.
 *
 * The handler emits this script BEFORE the client (`panel/studio.js`), so
 * `window.StudioMidi` is there when the client boots.
 *
 * ## What it owns
 *
 * - **The permission.** `connect()` is the only thing that ever calls
 *   `navigator.requestMIDIAccess({ sysex: false })`, and the page calls it from
 *   the **Connect controllers** button — a real user gesture, which is what a
 *   browser demands. Once the operator has said yes the yes is remembered in
 *   `localStorage` under `studio-midi-granted`, and `requestIfGranted()` asks
 *   again on a later page load ONLY while the browser still reports the
 *   permission as granted (`navigator.permissions.query({name: 'midi'})`).
 *   Without that API — or with the state still `prompt` — nothing is requested
 *   and the button is the way in.
 * - **The ports.** Every input's messages are parsed here and handed to the
 *   page as one plain object:
 *
 *     `{device_name, type: "note"|"cc"|"pc", channel: 1-16, number, value, on}`
 *
 *   `on` is a note on with a velocity above zero, or a control change at 64 or
 *   above (a pedal's press, which is what the performance effects hold on).
 *   Clock, active sensing, sysex, aftertouch and pitch bend are not messages
 *   Studio has an action for, so they are dropped here rather than routed.
 * - **The device list.** `devices()` answers `[{id, name, state}]` for the
 *   access's inputs, and `onDevices()` follows it as ports come and go. A port
 *   that is unplugged and plugged back in is re-attached on the spot — a
 *   browser may hand back the same port object or a fresh one with the same
 *   name — and because a mapping is stored against the controller's NAME, a
 *   mapping made before the unplug keeps working after it.
 *
 * Nothing here routes anything: the page's router (client.js, with the song's
 * own `midi_maps`) decides what a message runs, and only the one page holding
 * the song's routing Web Lock ever gets as far as running it.
 *
 * `close()` lets go of every port again (used by a teardown, so a Turbo visit
 * does not leave a second listener behind).
 *
 * @type {string}
 */
export const MIDI_SCRIPT = [
  "(function () {",
  "  'use strict';",
  "",
  "  // The operator's yes, per browser. Web MIDI has no permission API of its own",
  "  // for a page to inspect, so this is the memory of the click plus whatever",
  "  // navigator.permissions reports when the browser has that.",
  "  var GRANTED_KEY = 'studio-midi-granted';",
  "",
  "  var access = null;",
  "  var opening = null;",
  "  var messageListeners = [];",
  "  var deviceListeners = [];",
  "  // One entry per port this script has a listener on: {port, handler}.",
  "  var attached = [];",
  "",
  "  function messageOf(err) {",
  "    if (err && err.message) return String(err.message);",
  "    return 'This browser would not open MIDI controllers.';",
  "  }",
  "",
  "  function storage() {",
  "    try {",
  "      return window.localStorage || null;",
  "    } catch (err) {",
  "      return null;",
  "    }",
  "  }",
  "",
  "  function grantedBefore() {",
  "    var store = storage();",
  "    if (!store) return false;",
  "    try {",
  "      return store.getItem(GRANTED_KEY) === 'yes';",
  "    } catch (err) {",
  "      return false;",
  "    }",
  "  }",
  "",
  "  function rememberGranted() {",
  "    var store = storage();",
  "    if (!store) return;",
  "    try {",
  "      store.setItem(GRANTED_KEY, 'yes');",
  "    } catch (err) {",
  "      // A browser that keeps no storage simply asks again next time.",
  "    }",
  "  }",
  "",
  "  // A controller's name, as its port names it: what a mapping is stored",
  "  // against, so the name has to survive a query argument being absent.",
  "  function portName(port) {",
  "    var name = port && port.name ? String(port.name) : '';",
  "    if (name) return name;",
  "    var maker = port && port.manufacturer ? String(port.manufacturer) : '';",
  "    return maker ? maker + ' controller' : 'Controller';",
  "  }",
  "",
  "  function portId(port) {",
  "    var id = port && port.id ? String(port.id) : '';",
  "    return id || portName(port);",
  "  }",
  "",
  "  // One status byte and its data bytes as the page's own message, or null for",
  "  // what Studio has no action for (clock, active sensing, sysex, aftertouch,",
  "  // pitch bend, and anything malformed).",
  "  function parse(port, data) {",
  "    if (!data || typeof data.length !== 'number' || data.length < 1) return null;",
  "    var status = Number(data[0]) || 0;",
  "    if (status < 128) return null;",
  "    var command = status - (status % 16);",
  "    var channel = (status % 16) + 1;",
  "    var deviceName = portName(port);",
  "    if (command === 144) {",
  "      var velocity = Number(data[2]) || 0;",
  "      return {",
  "        device_name: deviceName, type: 'note', channel: channel,",
  "        number: Number(data[1]) || 0, value: velocity, on: velocity > 0",
  "      };",
  "    }",
  "    if (command === 128) {",
  "      return {",
  "        device_name: deviceName, type: 'note', channel: channel,",
  "        number: Number(data[1]) || 0, value: Number(data[2]) || 0, on: false",
  "      };",
  "    }",
  "    if (command === 176) {",
  "      var amount = Number(data[2]) || 0;",
  "      return {",
  "        device_name: deviceName, type: 'cc', channel: channel,",
  "        number: Number(data[1]) || 0, value: amount, on: amount >= 64",
  "      };",
  "    }",
  "    if (command === 192) {",
  "      var program = Number(data[1]) || 0;",
  "      return {",
  "        device_name: deviceName, type: 'pc', channel: channel,",
  "        number: program, value: program, on: true",
  "      };",
  "    }",
  "    return null;",
  "  }",
  "",
  "  // One message from one port: parsed once, handed to every listener that",
  "  // asked. A listener that throws is that listener's problem, never the next",
  "  // one's.",
  "  function deliver(port, data) {",
  "    if (!port) return;",
  "    var message = parse(port, data);",
  "    if (!message) return;",
  "    var listeners = messageListeners.slice(0);",
  "    for (var i = 0; i < listeners.length; i += 1) {",
  "      try {",
  "        listeners[i](message);",
  "      } catch (err) {",
  "        // Another listener still gets the message.",
  "      }",
  "    }",
  "  }",
  "",
  "  // Every input the access holds, connected or not: a browser keeps an",
  "  // unplugged port in the map with its state set to disconnected.",
  "  function inputsNow() {",
  "    var list = [];",
  "    if (!access || !access.inputs) return list;",
  "    var inputs = access.inputs;",
  "    try {",
  "      if (typeof inputs.forEach === 'function') {",
  "        inputs.forEach(function (port) {",
  "          if (port) list.push(port);",
  "        });",
  "      } else if (typeof inputs.values === 'function') {",
  "        var step = inputs.values();",
  "        var next = step.next();",
  "        while (!next.done) {",
  "          if (next.value) list.push(next.value);",
  "          next = step.next();",
  "        }",
  "      }",
  "    } catch (err) {",
  "      return list;",
  "    }",
  "    return list;",
  "  }",
  "",
  "  // The device list the page draws, in name order so it does not jump about",
  "  // when a browser hands ports back in another order.",
  "  function deviceList() {",
  "    var ports = inputsNow();",
  "    var out = [];",
  "    for (var i = 0; i < ports.length; i += 1) {",
  "      var port = ports[i];",
  "      out.push({",
  "        id: portId(port),",
  "        name: portName(port),",
  "        state: port.state === 'disconnected' ? 'disconnected' : 'connected'",
  "      });",
  "    }",
  "    out.sort(function (left, right) {",
  "      var a = String(left.name).toLowerCase();",
  "      var b = String(right.name).toLowerCase();",
  "      if (a < b) return -1;",
  "      if (a > b) return 1;",
  "      return 0;",
  "    });",
  "    return out;",
  "  }",
  "",
  "  function attachedTo(port) {",
  "    for (var i = 0; i < attached.length; i += 1) {",
  "      if (attached[i].port === port) return attached[i];",
  "    }",
  "    return null;",
  "  }",
  "",
  "  function detach(entry) {",
  "    if (!entry) return;",
  "    try {",
  "      if (entry.port && entry.port.onmidimessage === entry.handler) entry.port.onmidimessage = null;",
  "    } catch (err) {",
  "      // A port that refuses to let go is gone anyway.",
  "    }",
  "    var at = attached.indexOf(entry);",
  "    if (at >= 0) attached.splice(at, 1);",
  "  }",
  "",
  "  // Listen to one port. A port that comes back — the same object with its",
  "  // state back to connected, or a fresh object with the same name — is",
  "  // attached here, which is what makes a mapping survive an unplug.",
  "  function attach(port) {",
  "    if (!port) return;",
  "    if (attachedTo(port)) return;",
  "    var handler = function (event) {",
  "      deliver(port, event && event.data ? event.data : null);",
  "    };",
  "    try {",
  "      port.onmidimessage = handler;",
  "    } catch (err) {",
  "      return;",
  "    }",
  "    attached.push({ port: port, handler: handler });",
  "  }",
  "",
  "  // Forget the ports that are no longer in the access at all.",
  "  function forgetGone(ports) {",
  "    for (var i = attached.length - 1; i >= 0; i -= 1) {",
  "      var entry = attached[i];",
  "      var live = false;",
  "      for (var j = 0; j < ports.length; j += 1) {",
  "        if (ports[j] === entry.port) live = true;",
  "      }",
  "      if (live) continue;",
  "      detach(entry);",
  "    }",
  "  }",
  "",
  "  // Attach what is connected, forget what is gone, and tell the page what the",
  "  // list looks like now. The statechange handler and connect() both land here.",
  "  function refresh() {",
  "    var ports = inputsNow();",
  "    forgetGone(ports);",
  "    for (var i = 0; i < ports.length; i += 1) {",
  "      if (ports[i].state === 'disconnected') continue;",
  "      attach(ports[i]);",
  "    }",
  "    var list = deviceList();",
  "    var listeners = deviceListeners.slice(0);",
  "    for (var j = 0; j < listeners.length; j += 1) {",
  "      try {",
  "        listeners[j](list);",
  "      } catch (err) {",
  "        // One listener's error is not the next one's.",
  "      }",
  "    }",
  "    return list;",
  "  }",
  "",
  "  // Ask the browser for the controllers. ONLY from a user gesture: the page",
  "  // calls this from the Connect controllers button, and from nowhere else",
  "  // until the permission is granted already (see requestIfGranted).",
  "  function connect() {",
  "    if (access) return Promise.resolve(refresh());",
  "    if (opening) return opening;",
  "    var asked = null;",
  "    try {",
  "      if (!navigator || typeof navigator.requestMIDIAccess !== 'function') {",
  "        return Promise.reject(new Error('This browser has no Web MIDI.'));",
  "      }",
  "      asked = navigator.requestMIDIAccess({ sysex: false });",
  "    } catch (err) {",
  "      return Promise.reject(new Error(messageOf(err)));",
  "    }",
  "    opening = Promise.resolve(asked).then(function (opened) {",
  "      opening = null;",
  "      if (!opened) throw new Error('This browser would not open MIDI controllers.');",
  "      access = opened;",
  "      rememberGranted();",
  "      try {",
  "        access.onstatechange = function () { refresh(); };",
  "      } catch (err) {",
  "        // An access that reports no state changes still plays.",
  "      }",
  "      return refresh();",
  "    }, function (err) {",
  "      opening = null;",
  "      throw new Error(messageOf(err));",
  "    });",
  "    return opening;",
  "  }",
  "",
  "  // Ask again without a click, but only for a browser that already said yes to",
  "  // this page and still reports MIDI as granted. Anything else waits for the",
  "  // button, because a request without a gesture can only be refused.",
  "  function requestIfGranted() {",
  "    if (!grantedBefore()) return Promise.resolve(false);",
  "    var perms = null;",
  "    try {",
  "      perms = navigator && navigator.permissions ? navigator.permissions : null;",
  "    } catch (err) {",
  "      perms = null;",
  "    }",
  "    if (!perms || typeof perms.query !== 'function') return Promise.resolve(false);",
  "    var asked = null;",
  "    try {",
  "      asked = perms.query({ name: 'midi' });",
  "    } catch (err) {",
  "      return Promise.resolve(false);",
  "    }",
  "    return Promise.resolve(asked).then(function (status) {",
  "      if (!status || status.state !== 'granted') return false;",
  "      return connect().then(function () { return true; }, function () { return false; });",
  "    }, function () {",
  "      return false;",
  "    });",
  "  }",
  "",
  "  function onMessage(listener) {",
  "    if (typeof listener !== 'function') return function () {};",
  "    messageListeners.push(listener);",
  "    return function () {",
  "      var at = messageListeners.indexOf(listener);",
  "      if (at >= 0) messageListeners.splice(at, 1);",
  "    };",
  "  }",
  "",
  "  function onDevices(listener) {",
  "    if (typeof listener !== 'function') return function () {};",
  "    deviceListeners.push(listener);",
  "    return function () {",
  "      var at = deviceListeners.indexOf(listener);",
  "      if (at >= 0) deviceListeners.splice(at, 1);",
  "    };",
  "  }",
  "",
  "  function devices() {",
  "    return access ? deviceList() : [];",
  "  }",
  "",
  "  function isOpen() {",
  "    return !!access;",
  "  }",
  "",
  "  // Let every port go again: a teardown calls this, so the page that replaces",
  "  // this one starts with no listener of its own left behind.",
  "  function close() {",
  "    while (attached.length) detach(attached[attached.length - 1]);",
  "    if (access) {",
  "      try {",
  "        access.onstatechange = null;",
  "      } catch (err) {",
  "        // An access that refuses the assignment is going away anyway.",
  "      }",
  "    }",
  "    access = null;",
  "    opening = null;",
  "    messageListeners = [];",
  "    deviceListeners = [];",
  "  }",
  "",
  "  window.StudioMidi = {",
  "    connect: connect,",
  "    requestIfGranted: requestIfGranted,",
  "    devices: devices,",
  "    onMessage: onMessage,",
  "    onDevices: onDevices,",
  "    isOpen: isOpen,",
  "    close: close",
  "  };",
  "})();",
].join("\n");